-- ====================================================================

-- 1. Đảm bảo bảng study_notes đã tồn tại
CREATE TABLE IF NOT EXISTS study_notes (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  category TEXT NOT NULL,
  summary TEXT,
  tags JSONB DEFAULT '[]'::jsonb,
  items JSONB NOT NULL DEFAULT '[]'::jsonb,
  original_image_url TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now())
);

ALTER TABLE study_notes ENABLE ROW LEVEL SECURITY;

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'study_notes' AND policyname = 'Allow public read study_notes') THEN
    CREATE POLICY "Allow public read study_notes" ON study_notes FOR SELECT USING (true);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'study_notes' AND policyname = 'Allow public insert study_notes') THEN
    CREATE POLICY "Allow public insert study_notes" ON study_notes FOR INSERT WITH CHECK (true);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'study_notes' AND policyname = 'Allow public update study_notes') THEN
    CREATE POLICY "Allow public update study_notes" ON study_notes FOR UPDATE USING (true);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'study_notes' AND policyname = 'Allow public delete study_notes') THEN
    CREATE POLICY "Allow public delete study_notes" ON study_notes FOR DELETE USING (true);
  END IF;
END $$;

